<?php
require_once __DIR__.'/accounting-core.php';
// Reads existing ERP entities only. It never changes invoices, stock, payments or SUNAT state.
class CoSources {
 private $s;
 public function __construct(CoService $s){$this->s=$s;}
 private function refresh($company,$kind,$id){$queries=['sale'=>'SELECT FechaDoc date,IdAlmacen warehouse FROM Ve_DocVenta WHERE idDocVenta=?','purchase'=>'SELECT MovimientoFecha date,IdAlmacenDestino warehouse FROM Lo_Movimiento WHERE Hash=?','cash'=>'SELECT FechaDoc date,IdCuenta legacyAccount FROM Cb_CajaBanco WHERE IdCajaBanco=?'];if(!isset($queries[$kind]))throw new InvalidArgumentException('Origen inválido.');$row=$this->s->one($queries[$kind],[$id]);if(!$row)throw new InvalidArgumentException('El documento de origen ya no está disponible.');if($kind==='cash'){$binding=$this->s->one('SELECT Id FROM Co_Bank WHERE CompanyId=? AND LegacyId=?',[$company,$row['legacyAccount']]);}else{$binding=$this->s->one('SELECT Id FROM Co_Branch WHERE CompanyId=? AND WarehouseId=?',[$company,$row['warehouse']]);}if(!$binding)throw new InvalidArgumentException('El documento cambió de almacén/cuenta y ya no pertenece a esta empresa.');$date=substr($row['date'],0,10);$this->capture($company,['from'=>$date,'to'=>$date]);}
 public function capture($company,array $p){
  $this->s->permit($company,'draft');$from=coDate($p['from']??'');$to=coDate($p['to']??'');if($from>$to||(new DateTime($from))->diff(new DateTime($to))->days>366)throw new InvalidArgumentException('Sincroniza hasta un año por lote.');
  $bindings=$this->s->rows('SELECT * FROM Co_Branch WHERE CompanyId=? AND WarehouseId IS NOT NULL',[$company]);if(!$bindings&&!$this->s->one('SELECT Id FROM Co_Bank WHERE CompanyId=? AND LegacyId IS NOT NULL LIMIT 1',[$company]))throw new InvalidArgumentException('Asigna primero almacenes a las sucursales de esta empresa.');$snapshots=[];
  foreach($bindings as $b){
   $sales=$this->s->rows("SELECT v.idDocVenta id,v.FechaDoc date,v.Anulado cancelled,v.IdCliente partyId,c.Cliente partyName,c.DniRuc partyDoc,t.CodSunat docType,t.CodigoIgv affectation,t.TieneIgv taxed,v.Serie series,v.Numero number,v.EsCredito credit,v.CodSunatModifica referenceType,v.NroComprobanteModifica referenceDoc FROM Ve_DocVenta v JOIN Ve_DocVentaTipoDoc t ON t.IdTipoDoc=v.IdTipoDoc LEFT JOIN Ve_DocVentaCliente c ON c.IdCliente=v.IdCliente WHERE v.IdAlmacen=? AND v.FechaDoc>=? AND v.FechaDoc<DATE_ADD(?,INTERVAL 1 DAY) AND (t.VaRegVenta=1 OR t.CodSunat IN ('01','03','07','08','99')) ORDER BY v.idDocVenta LIMIT 5001",[$b['WarehouseId'],$from,$to]);
   if(count($sales)>5000)throw new InvalidArgumentException('Hay más de 5000 ventas. Reduce el rango.');
   foreach($sales as $sale){$sale['kind']='sale';$sale['branchId']=$b['Id'];$sale['currency']='PEN';$sale['rate']='1';$sale['date']=substr($sale['date'],0,10);$sale['lines']=$this->s->rows("SELECT d.IdProducto productId,p.Producto name,p.OpcContable productType,d.Cantidad quantity,CAST(ROUND(d.Cantidad*d.Precio-COALESCE(d.Descuento,0),2) AS CHAR) total,CASE WHEN d.PrecioCosto IS NULL THEN NULL ELSE CAST(ROUND(d.Cantidad*d.PrecioCosto,2) AS CHAR) END cost FROM Ve_DocVentaDet d LEFT JOIN Gen_Producto p ON p.IdProducto=d.IdProducto WHERE d.IdDocVenta=? ORDER BY d.IdDocVentaDet",[$sale['id']]);$snapshots[]=$sale;}
   $purchases=$this->s->rows("SELECT m.Hash id,m.MovimientoFecha date,m.Anulado cancelled,m.IdProveedor partyId,p.Proveedor partyName,p.Ruc partyDoc,t.CodSunat docType,m.Serie series,m.Numero number,m.Moneda currency,m.TipoCambio rate,m.FechaPeriodoTributario taxDate,m.NroComprobanteModifica referenceDoc FROM Lo_Movimiento m JOIN Lo_MovimientoTipo t ON t.IdMovimientoTipo=m.IdMovimientoTipo LEFT JOIN Lo_Proveedor p ON p.IdProveedor=m.IdProveedor WHERE m.IdAlmacenDestino=? AND m.MovimientoFecha>=? AND m.MovimientoFecha<DATE_ADD(?,INTERVAL 1 DAY) AND t.VaRegCompra=1 ORDER BY m.Hash LIMIT 5001",[$b['WarehouseId'],$from,$to]);
   if(count($purchases)>5000)throw new InvalidArgumentException('Hay más de 5000 compras. Reduce el rango.');
   foreach($purchases as $buy){$buy['kind']='purchase';$buy['branchId']=$b['Id'];$buy['date']=substr($buy['date'],0,10);$buy['lines']=$this->s->rows("SELECT d.IdProducto productId,p.Producto name,p.OpcContable productType,d.TieneIgv taxed,CAST(ROUND(d.Cantidad*d.Precio,2) AS CHAR) total,CAST(COALESCE(d.ISC,0) AS CHAR) isc,CAST(COALESCE(d.FLETE,0) AS CHAR) freight FROM Lo_MovimientoDetalle d LEFT JOIN Gen_Producto p ON p.IdProducto=d.IdProducto WHERE d.hashMovimiento=? ORDER BY d.IdProducto,d.IdLote,d.Precio",[$buy['id']]);$snapshots[]=$buy;}
  }
  $cash=$this->s->rows("SELECT c.IdCajaBanco id,c.FechaDoc date,c.Anulado cancelled,c.Concepto memo,c.Importe amount,c.IdProveedor supplierId,c.IdCliente customerId,t.Tipo direction,b.Account bankAccount,b.Currency currency FROM Cb_CajaBanco c JOIN Cb_TipoCajaBanco t ON t.IdTipoCajaBanco=c.IdTipoCajaBanco JOIN Co_Bank b ON b.LegacyId=c.IdCuenta AND b.CompanyId=? WHERE c.FechaDoc>=? AND c.FechaDoc<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY c.IdCajaBanco LIMIT 5001",[$company,$from,$to]);
  if(count($cash)>5000)throw new InvalidArgumentException('Hay más de 5000 movimientos. Reduce el rango.');
  foreach($cash as $row){$row['kind']='cash';$row['date']=substr($row['date'],0,10);$row['rate']='1';$row['branchId']=null;$snapshots[]=$row;}
  return $this->s->transaction(function()use($company,$snapshots){$counts=['captured'=>0,'unchanged'=>0,'conflicts'=>0];foreach($snapshots as $snap){$hash=hash('sha256',coJson($snap));$id=(string)$snap['id'];$kind=$snap['kind'];$old=$this->s->one('SELECT * FROM Co_Source WHERE CompanyId=? AND Kind=? AND SourceId=? FOR UPDATE',[$company,$kind,$id]);if($old&&$old['SourceHash']===$hash){$counts['unchanged']++;continue;}$state=$old&&$old['EntryId']?'conflict':($kind==='cash'&&(int)$snap['direction']===2?'ignored':'pending');$reason=$state==='conflict'?'El documento ERP cambió después de generar el asiento. Revisa el asiento vinculado; no se sobrescribe.':(!empty($snap['cancelled'])?'Documento anulado; no genera asiento nuevo.':'Revisa afectación, crédito fiscal, clasificación y costos históricos antes de generar.');
    $this->s->exec('INSERT INTO Co_Source(CompanyId,Kind,SourceId,SourceHash,Snapshot,State,Reason,CapturedAt) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE SourceHash=VALUES(SourceHash),Snapshot=VALUES(Snapshot),State=VALUES(State),Reason=VALUES(Reason),CapturedAt=VALUES(CapturedAt),Revision=Revision+1',[$company,$kind,$id,$hash,coJson($snap),$state,$reason,coNow()]);$counts[$state==='conflict'?'conflicts':'captured']++;}
   $this->s->audit($company,'capture','sources','batch',$counts);return $counts;});
 }
 public function prepare($company,array $p){
  $c=$this->s->permit($company,'review');$this->refresh($company,$p['kind']??'',(string)($p['sourceId']??''));return $this->s->transaction(function()use($company,$p,$c){$source=$this->s->one('SELECT * FROM Co_Source WHERE CompanyId=? AND Kind=? AND SourceId=? FOR UPDATE',[$company,$p['kind']??'',(string)($p['sourceId']??'')]);if(!$source||$source['SourceHash']!==($p['hash']??''))throw new InvalidArgumentException('El origen cambió. Recarga la vista previa.');
   if($source['EntryId']){if($source['State']==='generated')return ['id'=>(int)$source['EntryId'],'duplicate'=>true];throw new InvalidArgumentException('Conflicto: revierte y revisa el documento antes de generar otro asiento.');}
   if(empty($p['reviewed']))throw new InvalidArgumentException('Confirma la revisión de los datos de origen.');$d=json_decode($source['Snapshot'],true);if(!empty($d['cancelled']))throw new InvalidArgumentException('Documento anulado. No se contabiliza como operación nueva.');
   $tax=coTax($p['tax']??[]);if($tax['kind']!==$source['Kind']||$tax['issueDate']!==$d['date']||$tax['docType']!==$d['docType']||$tax['partyDoc']!==$d['partyDoc']||$tax['series']!==(string)$d['series']||$tax['number']!==(string)$d['number'])throw new InvalidArgumentException('Los datos tributarios deben corresponder al documento de origen.');
   $sum=0;foreach($d['lines'] as $l)$sum+=coMoney($l['total']);if($sum!==$tax['total'])throw new InvalidArgumentException('El total tributario no coincide con el ERP. Revisa ISC/flete/descuentos u otros importes.');
   $map=$c['settings']['accounts']??[];$account=function($key)use($map){if(empty($map[$key]))throw new InvalidArgumentException('Configura la cuenta predeterminada '.$key);return $map[$key];};$lines=[];$sign=$tax['sign'];$isSale=$source['Kind']==='sale';$partyType=$isSale?'customer':'supplier';
   $line=function($code,$amount,$debit,$flow='')use(&$lines,$sign,$d,$partyType){if(!$amount)return;$isDebit=$sign===1?$debit:!$debit;$lines[]=['account'=>$code,'debit'=>$isDebit?coAmount($amount):'0','credit'=>$isDebit?'0':coAmount($amount),'partyType'=>$partyType,'partyId'=>(string)$d['partyId'],'cashFlow'=>$flow];};
   $line($account($isSale?'receivable':'payable'),$tax['total'],$isSale);
   $base=$tax['taxable']+$tax['exempt']+$tax['unaffected'];
   if($isSale){$goods=0;$services=0;foreach($d['lines'] as $l){if(!in_array((int)$l['productType'],[1,2],true))throw new InvalidArgumentException('Producto sin clasificación mercadería/servicio.');if((int)$l['productType']===1)$goods+=coMoney($l['total']);else $services+=coMoney($l['total']);}$baseGoods=$sum?intdiv($base*$goods+intdiv($sum,2),$sum):0;$line($account('sales_goods'),$baseGoods,false);$line($account('sales_services'),$base-$baseGoods,false);
    if($tax['igv'])$line($account('igv_output'),$tax['igv'],false);if($tax['otherTaxes'])$line($account('other_tax_payable'),$tax['otherTaxes'],false);
    if($goods||$tax['freeAmount']){$cost=0;foreach($d['lines'] as $l)if((int)$l['productType']===1){if($l['cost']===null)throw new InvalidArgumentException('Falta costo histórico. Registra un ajuste revisado; no se usa el costo actual.');$cost+=coMoney($l['cost']);}if($tax['docType']==='07'&&empty($p['returnsInventory']))$cost=0;if($cost){$line($account($tax['total']===0?'free_delivery_expense':'cost_goods'),$cost,true);$line($account('inventory'),$cost,false);}}
   }else{$inventory=($p['purchaseClass']??'')==='inventory';$purchaseAccount=$inventory?$account('purchase_goods'):(($p['purchaseClass']??'')==='expense'?$account('expense'):'');if(!$purchaseAccount)throw new InvalidArgumentException('Clasifica la compra como inventario o gasto.');$purchaseCost=$base+(!$tax['creditEligible']?$tax['igv']:0)+$tax['otherTaxes'];$line($purchaseAccount,$purchaseCost,true);if($inventory){$line($account('inventory'),$purchaseCost,true);$line($account('inventory_variation'),$purchaseCost,false);}if($tax['igv']&&$tax['creditEligible'])$line($account('igv_input'),$tax['igv'],true);}
   if($isSale&&$tax['freeIgv']){$line($account('free_tax_expense'),$tax['freeIgv'],true);$line($account('igv_output'),$tax['freeIgv'],false);}
   if($tax['perception']){if($isSale){$line($account('receivable'),$tax['perception'],true);$line($account('perception_payable'),$tax['perception'],false);}else{$line($account('perception_credit'),$tax['perception'],true);$line($account('payable'),$tax['perception'],false);}}
   $currency=$p['currency']??$d['currency'];if(in_array($currency,['S','SOLES','1',''],true))$currency='PEN';if(in_array($currency,['D','DOLARES','2'],true))$currency='USD';if($isSale&&$currency!=='PEN')throw new InvalidArgumentException('El origen de ventas no guarda moneda extranjera por comprobante; registra el caso multimoneda como asiento documental revisado.');$rate=$currency==='PEN'?'1':($p['rate']??$d['rate']);
   $entry=$this->s->insertDraft($company,['date'=>$d['date'],'branchId'=>$d['branchId'],'currency'=>$currency,'rate'=>(string)$rate,'memo'=>($isSale?'Venta ':'Compra ').$d['series'].'-'.$d['number'],'document'=>$d['docType'].':'.$d['series'].'-'.$d['number'],'sourceType'=>'erp_'.$source['Kind'],'sourceId'=>$source['SourceId'].':r'.$source['Revision'],'lines'=>$lines,'tax'=>$p['tax']],$c);
   $this->s->exec("UPDATE Co_Source SET State='generated',EntryId=?,Reason='' WHERE CompanyId=? AND Kind=? AND SourceId=?",[$entry['id'],$company,$source['Kind'],$source['SourceId']]);$this->s->audit($company,'review_source','source',$source['SourceId'],['hash'=>$source['SourceHash'],'entry'=>$entry['id']]);return $entry;
  });
 }
 public function resolve($company,array $p){$this->s->permit($company,'review');$this->refresh($company,$p['kind']??'',(string)($p['sourceId']??''));return $this->s->transaction(function()use($company,$p){$source=$this->s->one('SELECT * FROM Co_Source WHERE CompanyId=? AND Kind=? AND SourceId=? FOR UPDATE',[$company,$p['kind']??'',(string)($p['sourceId']??'')]);if(!$source||$source['SourceHash']!==($p['hash']??''))throw new InvalidArgumentException('El origen cambió.');$reason=coText($p['reason']??'',500,true);$snapshot=json_decode($source['Snapshot'],true);if($source['EntryId']){$entry=$this->s->entry($company,$source['EntryId']);$reversal=$this->s->one("SELECT Id FROM Co_Entry WHERE CompanyId=? AND ReversalOf=? AND Status='posted'",[$company,$source['EntryId']]);if($entry['Status']!=='discarded'&&!$reversal)throw new InvalidArgumentException('Descarta el borrador anterior o contabiliza su reverso antes de resolver.');}if(!empty($p['manualEntryId'])){if(!empty($snapshot['cancelled']))throw new InvalidArgumentException('No vincules una operación anulada como venta/compra vigente.');$manual=$this->s->entry($company,(int)$p['manualEntryId']);$document=($snapshot['docType']??'').':'.($snapshot['series']??'').'-'.($snapshot['number']??'');if($manual['Status']!=='posted'||$manual['SourceType']!=='manual'||$manual['Document']!==$document)throw new InvalidArgumentException('El asiento manual debe estar contabilizado y referenciar exactamente '.$document);$this->s->exec("UPDATE Co_Source SET EntryId=?,State='generated',Reason=? WHERE CompanyId=? AND Kind=? AND SourceId=?",[$manual['Id'],$reason,$company,$source['Kind'],$source['SourceId']]);$this->s->audit($company,'link_manual','source',$source['SourceId'],['entry'=>$manual['Id'],'reason'=>$reason]);return ['state'=>'generated','id'=>$manual['Id']];}$state=!empty($snapshot['cancelled'])?'ignored':'pending';$this->s->exec('UPDATE Co_Source SET EntryId=NULL,State=?,Reason=?,Revision=Revision+1 WHERE CompanyId=? AND Kind=? AND SourceId=?',[$state,$reason,$company,$source['Kind'],$source['SourceId']]);$this->s->audit($company,'resolve_source','source',$source['SourceId'],['oldEntry'=>$source['EntryId'],'reason'=>$reason,'state'=>$state]);return ['state'=>$state];});}
 public function prepareCash($company,array $p){$c=$this->s->permit($company,'review');$this->refresh($company,'cash',(string)($p['sourceId']??''));return $this->s->transaction(function()use($company,$p,$c){$source=$this->s->one("SELECT * FROM Co_Source WHERE CompanyId=? AND Kind='cash' AND SourceId=? FOR UPDATE",[$company,(string)($p['sourceId']??'')]);if(!$source||$source['SourceHash']!==($p['hash']??'')||empty($p['reviewed']))throw new InvalidArgumentException('Revisa el origen y confirma su clasificación.');if($source['EntryId']){if($source['State']==='generated')return ['id'=>(int)$source['EntryId'],'duplicate'=>true];throw new InvalidArgumentException('Resuelve primero el conflicto.');}$d=json_decode($source['Snapshot'],true);if($d['cancelled']||(int)$d['direction']===2)throw new InvalidArgumentException('El movimiento es anulado o neutral. No representa una salida/ingreso contable.');
  $types=['bank_expense'=>['bank_fees',1],'supplier_refund'=>['payable',0],'customer_refund'=>['receivable',1],'customer_receipt'=>['receivable',0],'supplier_payment'=>['payable',1],'cash_income'=>['other_income',0],'cash_expense'=>['expense',1],'payroll_payment'=>['payroll_payable',1]];$type=$p['operation']??'';if(!isset($types[$type])||$types[$type][1]!==(int)$d['direction'])throw new InvalidArgumentException('Clasificación incompatible con el ingreso/egreso del ERP.');$partyType=$d['supplierId']?'supplier':($d['customerId']?'customer':'');$partyId=(string)($d['supplierId']?:($d['customerId']?:''));if(in_array($type,['customer_receipt','customer_refund','supplier_payment','supplier_refund'],true)){$required=in_array($type,['supplier_payment','supplier_refund'],true)?'supplier':'customer';$sourceParty=$required==='supplier'?$d['supplierId']:$d['customerId'];$partyId=(string)($sourceParty?:($p['partyId']??''));if(!preg_match('/^[1-9]\d{0,18}$/',$partyId))throw new InvalidArgumentException('Falta identificar al cliente/proveedor del cobro o pago.');$sql=$required==='supplier'?'SELECT IdProveedor FROM Lo_Proveedor WHERE IdProveedor=?':'SELECT IdCliente FROM Ve_DocVentaCliente WHERE IdCliente=?';if(!$this->s->one($sql,[$partyId]))throw new InvalidArgumentException('Tercero no disponible.');$partyType=$required;}$counter=$c['settings']['accounts'][$types[$type][0]]??'';$amount=coMoney($d['amount']);$in=(int)$d['direction']===0;$debit=$in?$d['bankAccount']:$counter;$credit=$in?$counter:$d['bankAccount'];$rate=$d['currency']==='PEN'?'1':(string)($p['rate']??'');$flow=$p['cashFlow']??'operating';$entry=$this->s->insertDraft($company,['date'=>$d['date'],'currency'=>$d['currency'],'rate'=>$rate,'memo'=>$d['memo'],'document'=>'Caja ERP #'.$d['id'],'sourceType'=>'erp_cash','sourceId'=>$source['SourceId'].':r'.$source['Revision'],'lines'=>[['account'=>$debit,'debit'=>coAmount($amount),'credit'=>'0','cashFlow'=>$in?$flow:'','partyType'=>$partyType,'partyId'=>$partyId],['account'=>$credit,'debit'=>'0','credit'=>coAmount($amount),'cashFlow'=>$in?'':$flow,'partyType'=>$partyType,'partyId'=>$partyId]]],$c);$this->s->exec("UPDATE Co_Source SET State='generated',EntryId=?,Reason='' WHERE CompanyId=? AND Kind='cash' AND SourceId=?",[$entry['id'],$company,$source['SourceId']]);$this->s->audit($company,'review_source','cash',$d['id'],['entry'=>$entry['id'],'operation'=>$type]);return $entry;
 });}
}
